package com.argument.draft;

import com.argument.common.exception.*;
import com.argument.version.*;
import com.argument.version.port.AnnotationDependencies;
import com.argument.version.port.VersionIdentity.Actor;
import com.argument.membera.support.Utf16Offsets;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.argument.adjudication.AdjudicationService.require;

/** Ordinary annotator drafts use the same facts and case transaction as D submission. */
@Service
public class DraftService {
    private final AnnotationDependencies data;private final VersionService access;private final VersionRepository versions;private final ObjectMapper mapper;private final JdbcTemplate jdbc;private final DraftCommandValidator validator;
    public DraftService(AnnotationDependencies data,VersionService access,VersionRepository versions,ObjectMapper mapper,JdbcTemplate jdbc,DraftCommandValidator validator){this.data=data;this.access=access;this.versions=versions;this.mapper=mapper;this.jdbc=jdbc;this.validator=validator;}
    private ObjectNode assignment(Actor actor,String c,String id){
        var a=data.read("assignment",VersionJson.uuid(id));var member=data.read("member",a.path("taskMemberId").asText());var doc=data.read("taskDocument",c);
        require(actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR")&&actor.id().equals(a.path("userId").asText())&&c.equals(a.path("taskDocumentId").asText())&&"ACTIVE".equals(a.path("status").asText())&&"ANNOTATOR".equals(a.path("assignmentRole").asText())&&"ACTIVE".equals(member.path("status").asText())&&member.path("userId").equals(a.path("userId"))&&"ANNOTATOR".equals(member.path("memberRole").asText())&&member.path("taskId").equals(doc.path("taskId")),ErrorCode.BLIND_SCOPE_DENIED,"只能操作本人有效分配的草稿");return a;
    }
    private ObjectNode own(Actor actor,String id){var draft=data.read("draft",VersionJson.uuid(id));assignment(actor,draft.path("taskDocumentId").asText(),draft.path("assignmentId").asText());return draft;}
    private ObjectNode lockCase(String c){versions.lockCase(c);var doc=data.lock("taskDocument",c);data.lock("task",doc.path("taskId").asText());return doc;}
    private ObjectNode lockDraft(Actor actor,String id){var initial=own(actor,id);lockCase(initial.path("taskDocumentId").asText());var draft=data.lock("draft",id);assignment(actor,draft.path("taskDocumentId").asText(),draft.path("assignmentId").asText());return draft;}
    private void writable(ObjectNode draft){
        var doc=data.read("taskDocument",draft.path("taskDocumentId").asText());var task=data.read("task",doc.path("taskId").asText());
        require("ACTIVE".equals(draft.path("status").asText())&&"ANNOTATING".equals(doc.path("status").asText())&&"IN_PROGRESS".equals(task.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"草稿、任务或案例已锁定");
        require(draft.path("segmentationCheckpointId").equals(currentCheckpoint(doc).path("id")),ErrorCode.SEGMENTATION_NOT_CONFIRMED,"草稿未引用当前唯一统一关口");
    }
    private ObjectNode currentCheckpoint(ObjectNode doc){
        var rows=data.find("checkpoint","taskDocumentId",doc.path("id").asText()).stream().filter(cp->"CONFIRMED".equals(cp.path("status").asText())).toList();
        require(rows.size()==1,ErrorCode.SEGMENTATION_NOT_CONFIRMED,"需要唯一当前已确认的统一切割关口");var cp=rows.get(0);
        for(String f:List.of("taskDocumentId","documentTextVersionId","annotationScopeId"))require(cp.path(f).equals(doc.path(f.equals("taskDocumentId")?"id":f)),ErrorCode.SEGMENTATION_NOT_CONFIRMED,"关口与案例基准不一致");
        require(cp.path("agreementScore").asDouble()>0.8&&cp.path("unifiedBoundaries").isArray()&&!cp.path("unifiedBoundaries").isEmpty(),ErrorCode.SEGMENTATION_NOT_CONFIRMED,"统一切割未通过门槛");
        var text=data.read("text",doc.path("documentTextVersionId").asText());var scope=data.read("scope",doc.path("annotationScopeId").asText());
        require("CONFIRMED".equals(scope.path("status").asText())&&scope.path("documentTextVersionId").equals(doc.path("documentTextVersionId"))&&VersionJson.sha256(text.path("normalizedText").asText()).equals(text.path("contentSha256").asText()),ErrorCode.SOURCE_INCOMPLETE,"文本或范围基准不可用");
        Utf16Offsets.validate(text.path("normalizedText").asText(),scope.path("startOffset").asInt(),scope.path("endOffset").asInt(),mapper.convertValue(cp.path("unifiedBoundaries"),new TypeReference<List<Map<String,Object>>>(){}));return cp;
    }
    private ObjectNode view(ObjectNode draft){var result=mapper.createObjectNode();result.set("draft",draft);var cp=data.read("checkpoint",draft.path("segmentationCheckpointId").asText());for(String field:List.of("taskDocumentId","documentTextVersionId","annotationScopeId"))require(draft.path(field).equals(cp.path(field)),ErrorCode.SOURCE_INCOMPLETE,"草稿和关口来源不一致");var publicCheckpoint=cp.deepCopy();publicCheckpoint.retain(List.of("id","taskDocumentId","documentTextVersionId","annotationScopeId","sourceSubmissionIds","agreementScore","requiredThreshold","unifiedBoundaries","boundaryHash","status","confirmedById","confirmedAt","createdAt","createdById","updatedAt","updatedById","recordVersion"));result.set("segmentationCheckpoint",publicCheckpoint);return result;}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public ObjectNode mine(Actor actor,String c){
        var doc=data.read("taskDocument",VersionJson.uuid(c));require(actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR"),ErrorCode.BLIND_SCOPE_DENIED,"只能读取本人分配的草稿");
        var rows=data.find("draft","taskDocumentId",c).stream().filter(d->!"ABANDONED".equals(d.path("status").asText())).filter(d->{var a=data.read("assignment",d.path("assignmentId").asText());return actor.id().equals(a.path("userId").asText())&&"ACTIVE".equals(a.path("status").asText());}).toList();
        require(rows.size()<=1,ErrorCode.SOURCE_INCOMPLETE,"本人草稿存在歧义，请先处理来源");require(!rows.isEmpty(),ErrorCode.NOT_FOUND,"尚未创建本人草稿");return view(own(actor,rows.get(0).path("id").asText()));
    }
    @Transactional public ObjectNode create(Actor actor,String c,String key,ObjectNode body){
        validator.validate("A02",body);VersionJson.uuid(c);var doc=lockCase(c);assignment(actor,c,body.path("assignmentId").asText());String operation="A02:"+c;var cached=replay(actor,operation,key,body);if(cached!=null)return cached;
        require("IN_PROGRESS".equals(data.read("task",doc.path("taskId").asText()).path("status").asText())&&"ANNOTATING".equals(doc.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"任务未进入可标注阶段");
        var cp=currentCheckpoint(doc);if(body.hasNonNull("segmentationCheckpointId"))require(cp.path("id").equals(body.get("segmentationCheckpointId")),ErrorCode.SEGMENTATION_NOT_CONFIRMED,"不能选择历史或其他案例关口");
        labelsFor(doc);String assignment=body.path("assignmentId").asText();
        require(data.find("draft","taskDocumentId",c).stream().noneMatch(d->assignment.equals(d.path("assignmentId").asText())&&!"ABANDONED".equals(d.path("status").asText())),ErrorCode.ACTIVE_DRAFT_EXISTS,"本人已有草稿，请读取原草稿");
        require(versions.versions(c).stream().noneMatch(v->versions.effective(v)&&assignment.equals(v.path("assignmentId").asText())),ErrorCode.LOCKED_RESOURCE,"本人已有有效正式版本");
        var draft=mapper.createObjectNode();VersionJson.stamp(draft,actor.id(),VersionJson.now());for(String f:List.of("documentTextVersionId","annotationScopeId"))draft.set(f,doc.get(f));draft.put("taskDocumentId",c).put("assignmentId",assignment).put("status","ACTIVE").put("phase","ELEMENTS").put("revision",1).put("lastSavedAt",VersionJson.now());draft.set("segmentationCheckpointId",cp.get("id"));draft.putArray("elementIds");draft.putArray("relationIds");draft.putNull("graphId");append("draft",draft);var response=view(draft);saveReceipt(actor,operation,key,body,response,mapper.createObjectNode(),draft);return response;
    }
    @Transactional public ObjectNode save(Actor actor,String id,String key,int expected,ObjectNode body){
        validator.validate("A03",body);var draft=lockDraft(actor,id);String op="A03:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;writable(draft);version(draft,expected,"AnnotationDraft");var before=draft.deepCopy();
        for(String[] pair:new String[][]{{"elementIds","element"},{"relationIds","relation"}})if(body.has(pair[0])){
            var actual=ids(owned(pair[1],id));require(actual.equals(ids(body.path(pair[0])))&&actual.equals(ids(draft.path(pair[0]))),ErrorCode.CONFLICT,"集合必须与本草稿实体一致，请通过对应资源接口增删");
        }
        if(body.has("phase"))draft.set("phase",body.get("phase"));touchDraft(draft,actor);data.replace("draft",draft);saveReceipt(actor,op,key,body,draft,before,draft);return draft;
    }
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public ObjectNode elements(Actor actor,String id,String category,String q){var draft=own(actor,id);if(category!=null)require(Set.of("PROPOSITION","NON_PROPOSITION").contains(category),ErrorCode.VALIDATION_ERROR,"未知要素分类");var result=mapper.createObjectNode();var items=result.putArray("items");for(var e:orderedElements(id))if((category==null||e.path("isProposition").asBoolean()=="PROPOSITION".equals(category))&&(q==null||e.path("text").asText().contains(q)))items.add(e);return versions(result,draft);}
    private ObjectNode element(Actor actor,String id,boolean deleted){var rows=data.find("element","id",VersionJson.uuid(id));if(rows.isEmpty()&&deleted)rows=data.find("deletedElement","id",id);require(!rows.isEmpty(),ErrorCode.NOT_FOUND,"要素不存在");var e=rows.get(0);require("DRAFT".equals(e.path("ownerType").asText()),ErrorCode.FORBIDDEN,"不可修改冻结快照");own(actor,e.path("ownerId").asText());return e;}
    @Transactional public ObjectNode createElement(Actor actor,String id,String key,ObjectNode body){validator.validate("E02",body);var draft=lockDraft(actor,id);String op="E02:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;writable(draft);var before=draft.deepCopy();var e=mapper.createObjectNode();VersionJson.stamp(e,actor.id(),VersionJson.now());e.put("ownerType","DRAFT").put("ownerId",id);for(String f:List.of("documentTextVersionId","annotationScopeId"))e.set(f,draft.get(f));e.putArray("sourceElementIds");e.putNull("displayNo");mergeElement(e,body,draft);append("element",e);renumber(draft,actor,e.path("id").asText());touchDraft(draft,actor);invalidateGraph(draft,actor);data.replace("draft",draft);var response=elementResult(data.read("element",e.path("id").asText()),draft);saveReceipt(actor,op,key,body,response,before,draft);return response;}
    @Transactional public ObjectNode updateElement(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("E03",body);var e=element(actor,id,false);var draft=lockDraft(actor,e.path("ownerId").asText());e=data.lock("element",id);String op="E03:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;writable(draft);version(e,expected,"Element");var before=e.deepCopy();mergeElement(e,body,draft);if(before.path("isProposition").asBoolean()&&!e.path("isProposition").asBoolean())noRelationReference(id,draft);touch(e,actor);data.replace("element",e);renumber(draft,actor,id);touchDraft(draft,actor);invalidateGraph(draft,actor);data.replace("draft",draft);var response=elementResult(data.read("element",id),draft);saveReceipt(actor,op,key,body,response,before,e);return response;}
    @Transactional public ObjectNode deleteElement(Actor actor,String id,String key,int expected,ObjectNode body){validator.validate("E04",body);var e=element(actor,id,true);var draft=lockDraft(actor,e.path("ownerId").asText());String op="E04:"+id;var cached=replay(actor,op,key,body);if(cached!=null)return cached;e=data.lock("element",id);writable(draft);version(e,expected,"Element");require(!body.path("reason").asText().isBlank()&&body.path("reason").asText().length()<=2000,ErrorCode.VALIDATION_ERROR,"请填写删除理由");noRelationReference(id,draft);noGraphReference(id,draft);jdbc.update("UPDATE workflow_records SET object_kind='deletedElement' WHERE object_kind='element' AND object_id=?",id);renumber(draft,actor,null);touchDraft(draft,actor);invalidateGraph(draft,actor);data.replace("draft",draft);var response=versions(mapper.createObjectNode().put("id",id).put("deleted",true),draft);saveReceipt(actor,op,key,body,response,e,mapper.createObjectNode());return response;}
    private void mergeElement(ObjectNode e,ObjectNode body,ObjectNode draft){
        for(String f:List.of("startOffset","endOffset","labelCode"))if(body.has(f))e.set(f,body.get(f));int start=e.path("startOffset").asInt(-1),end=e.path("endOffset").asInt(-1);
        var cp=data.read("checkpoint",draft.path("segmentationCheckpointId").asText());boolean boundary=false;for(var row:cp.path("unifiedBoundaries"))if(row.path("startOffset").asInt()==start&&row.path("endOffset").asInt()==end)boundary=true;
        if(!boundary)throw new VersionFailure(ErrorCode.LOCKED_RESOURCE,"边界变更需要来源记录模型，当前仅支持统一边界上的标签编辑",Map.of("boundaryChangeRequiresModel",true,"objectType","AnnotationDraft","objectId",draft.path("id").asText()));
        require(owned("element",draft.path("id").asText()).stream().noneMatch(other->!other.path("id").equals(e.path("id"))&&start<other.path("endOffset").asInt()&&end>other.path("startOffset").asInt()),ErrorCode.CONFLICT,"同一草稿中存在重复或重叠要素");
        var doc=data.read("taskDocument",draft.path("taskDocumentId").asText());var matches=labelsFor(doc).stream().filter(l->l.path("code").equals(e.path("labelCode"))).toList();require(matches.size()==1,ErrorCode.VALIDATION_ERROR,"标签不属于当前绑定指南或不可使用");var label=matches.get(0);
        e.set("labelDefinitionId",label.get("id"));e.put("isProposition","PROPOSITION".equals(label.path("category").asText()));String text=data.read("text",draft.path("documentTextVersionId").asText()).path("normalizedText").asText();e.put("text",text.substring(start,end));
    }
    private void noRelationReference(String id,ObjectNode draft){for(var relation:owned("relation",draft.path("id").asText()))if("ACTIVE".equals(relation.path("status").asText()))for(var p:data.find("participant","relationId",relation.path("id").asText()))require(!("ELEMENT".equals(p.path("targetKind").asText())&&id.equals(p.path("targetId").asText())),ErrorCode.RELATION_REFERENCES_ELEMENT,"请先通过关系模块处理引用，不能自动删除关系");}
    private void noGraphReference(String id,ObjectNode draft){for(var graph:owned("graph",draft.path("id").asText())){require(!ids(graph.path("elementIds")).contains(id),ErrorCode.GRAPH_REFERENCES_ELEMENT,"论证图仍引用此要素，请先处理图引用");for(var layout:data.find("layout","graphId",graph.path("id").asText()))for(var p:layout.path("nodePositions"))require(!id.equals(p.path("targetId").asText()),ErrorCode.GRAPH_REFERENCES_ELEMENT,"图布局仍引用此要素");}}
    private void invalidateGraph(ObjectNode draft,Actor actor){if(draft.hasNonNull("graphId")){var graph=data.lock("graph",draft.path("graphId").asText());require("DRAFT".equals(graph.path("ownerType").asText())&&graph.path("ownerId").equals(draft.path("id")),ErrorCode.SOURCE_INCOMPLETE,"草稿论证图来源不一致");graph.put("status","INVALID");touch(graph,actor);data.replace("graph",graph);}}
    private void renumber(ObjectNode draft,Actor actor,String target){int n=0;var ids=draft.putArray("elementIds");for(var e:orderedElements(draft.path("id").asText())){JsonNode display=e.path("displayNo").deepCopy();if(e.path("isProposition").asBoolean())e.put("displayNo","P"+(++n));else e.putNull("displayNo");if(!display.equals(e.path("displayNo"))){if(!e.path("id").asText().equals(target))touch(e,actor);data.replace("element",e);}ids.add(e.path("id").asText());}}
    private List<ObjectNode> orderedElements(String id){var result=new ArrayList<>(owned("element",id));result.sort(Comparator.comparingInt((ObjectNode e)->e.path("startOffset").asInt()).thenComparingInt(e->e.path("endOffset").asInt()).thenComparing(e->e.path("id").asText()));return result;}
    private List<ObjectNode> owned(String kind,String id){var rows=data.find(kind,"ownerId",id);require(rows.stream().allMatch(n->"DRAFT".equals(n.path("ownerType").asText())),ErrorCode.SOURCE_INCOMPLETE,"草稿实体所有权不一致");return rows;}
    private Set<String> ids(List<ObjectNode> rows){var result=new HashSet<String>();for(var row:rows)result.add(row.path("id").asText());return result;}
    private Set<String> ids(JsonNode rows){require(rows.isArray(),ErrorCode.SOURCE_INCOMPLETE,"对象集合缺失");var result=new HashSet<String>();for(var id:rows)require(id.isTextual()&&result.add(VersionJson.uuid(id.asText())),ErrorCode.VALIDATION_ERROR,"对象集合包含重复或无效 ID");return result;}
    private List<ObjectNode> labelsFor(ObjectNode doc){String guideId=data.read("task",doc.path("taskId").asText()).path("guideVersionId").asText();var guides=data.find("guideVersion","id",guideId);require(guides.size()==1,ErrorCode.SOURCE_INCOMPLETE,"绑定指南尚未接入共享字典");var guide=guides.get(0);require(Set.of("PUBLISHED","ARCHIVED").contains(guide.path("status").asText()),ErrorCode.GUIDE_NOT_READY,"绑定指南不可用于标注");boolean version12=Set.of("v1.2","1.2").contains(guide.path("versionCode").asText());var rows=data.find("label","guideVersionId",guideId).stream().filter(l->!version12||!"GM-C".equals(l.path("code").asText())).toList();require(!rows.isEmpty(),ErrorCode.SOURCE_INCOMPLETE,"绑定指南没有可用标签");return rows;}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public ObjectNode workspace(Actor actor,String c){var view=mine(actor,c);var draft=(ObjectNode)view.get("draft");var doc=data.read("taskDocument",c);var result=view.deepCopy();result.set("elements",mapper.valueToTree(orderedElements(draft.path("id").asText())));result.set("labels",mapper.valueToTree(labelsFor(doc)));result.set("text",data.read("text",doc.path("documentTextVersionId").asText()));boolean editable="ACTIVE".equals(draft.path("status").asText())&&"ANNOTATING".equals(doc.path("status").asText())&&"IN_PROGRESS".equals(data.read("task",doc.path("taskId").asText()).path("status").asText());result.put("canWrite",editable);return result;}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public ObjectNode context(Actor actor,String c){
        var doc=data.read("taskDocument",VersionJson.uuid(c));require(actor.permission("ANNOTATION_WORK")&&access.hasAssignment(actor,c,"ANNOTATOR"),ErrorCode.BLIND_SCOPE_DENIED,"只能读取本人标注工作台");
        var assignments=data.find("assignment","taskDocumentId",c).stream().filter(a->actor.id().equals(a.path("userId").asText())&&"ACTIVE".equals(a.path("status").asText())&&"ANNOTATOR".equals(a.path("assignmentRole").asText())).toList();require(assignments.size()==1,ErrorCode.SOURCE_INCOMPLETE,"本人有效分配存在歧义");var a=assignment(actor,c,assignments.get(0).path("id").asText());
        var cp=currentCheckpoint(doc);ObjectNode result;
        ObjectNode existing=null;try{existing=mine(actor,c);}catch(BusinessException e){if(e.getErrorCode()!=ErrorCode.NOT_FOUND)throw e;}
        if(existing!=null)result=workspace(actor,c);else{result=mapper.createObjectNode();result.putNull("draft");result.set("segmentationCheckpoint",cp);result.putArray("elements");result.set("labels",mapper.valueToTree(labelsFor(doc)));result.set("text",data.read("text",doc.path("documentTextVersionId").asText()));result.put("canWrite",false);}
        result.set("assignment",a);boolean working="IN_PROGRESS".equals(data.read("task",doc.path("taskId").asText()).path("status").asText())&&"ANNOTATING".equals(doc.path("status").asText());result.put("canCreate",working&&result.path("draft").isNull()&&versions.versions(c).stream().noneMatch(v->versions.effective(v)&&a.path("id").equals(v.path("assignmentId"))));if(result.path("draft").isObject()&&!result.path("draft").path("segmentationCheckpointId").equals(cp.path("id")))result.put("canWrite",false);return result;
    }
    private void append(String kind,ObjectNode row){jdbc.update("INSERT INTO workflow_records(object_kind,object_id,payload_json) VALUES(?,?,?)",kind,row.path("id").asText(),row.toString());}
    private void touch(ObjectNode row,Actor actor){com.argument.adjudication.AdjudicationService.touch(row,actor);}
    private void touchDraft(ObjectNode draft,Actor actor){touch(draft,actor);draft.put("revision",draft.path("revision").asInt()+1).put("lastSavedAt",VersionJson.now());}
    private void version(ObjectNode resource,int expected,String type){if(expected!=resource.path("recordVersion").asInt())throw new VersionFailure(ErrorCode.VERSION_CONFLICT,"数据已变化，请刷新后重试",Map.of("objectType",type,"objectId",resource.path("id").asText(),"currentRecordVersion",resource.path("recordVersion").asInt()));}
    private ObjectNode replay(Actor actor,String operation,String key,ObjectNode body){return versions.receipt(actor.id(),operation,VersionJson.uuid(key),VersionJson.canonicalHash(body));}
    private void saveReceipt(Actor actor,String operation,String key,ObjectNode body,ObjectNode response,ObjectNode before,ObjectNode after){versions.receipt(actor.id(),operation,key,VersionJson.canonicalHash(body),response,before,after,body.path("reason").asText());}
    private ObjectNode versions(ObjectNode response,ObjectNode draft){return response.put("draftRecordVersion",draft.path("recordVersion").asInt()).put("draftRevision",draft.path("revision").asInt());}
    private ObjectNode elementResult(ObjectNode element,ObjectNode draft){var response=mapper.createObjectNode();response.set("element",element);return versions(response,draft);}
}
